const users = $input.all().map(item => item.json);
const now = new Date();

function calculateEngagementScore(user) {
  const scores = {};

  // 1. Recency Score (0-25): How recently did they use the platform?
  const lastActive = new Date(user.updatedAt || user.createdAt);
  const daysSinceActive = Math.floor((now - lastActive) / (1000 * 60 * 60 * 24));
  if (daysSinceActive <= 1) scores.recency = 25;
  else if (daysSinceActive <= 3) scores.recency = 20;
  else if (daysSinceActive <= 7) scores.recency = 15;
  else if (daysSinceActive <= 14) scores.recency = 8;
  else if (daysSinceActive <= 30) scores.recency = 3;
  else scores.recency = 0;

  // 2. Frequency Score (0-25): Login/usage pattern from timeSpentHistory
  const history = user.progress?.timeSpentHistory || [];
  const last7Days = history.filter(h => {
    const d = new Date(h.date);
    return (now - d) / (1000 * 60 * 60 * 24) <= 7;
  });
  const activeDaysLast7 = last7Days.filter(h => h.minutes > 0).length;
  scores.frequency = Math.min(25, Math.round((activeDaysLast7 / 7) * 25));

  // 3. Depth Score (0-25): How deeply do they engage?
  const lessonsViewed = user.lessonsCount || 0;
  const completionRate = user.completionRate || 0;
  const videosWatched = user.progress?.videosWatched || 0;
  const docsOpened = user.progress?.documentsOpened || 0;

  let depthRaw = 0;
  depthRaw += Math.min(8, lessonsViewed * 0.8);  // up to 8 points for lessons
  depthRaw += completionRate * 8;                  // up to 8 points for completion
  depthRaw += Math.min(5, videosWatched * 0.5);   // up to 5 points for videos
  depthRaw += Math.min(4, docsOpened * 0.4);      // up to 4 points for docs
  scores.depth = Math.min(25, Math.round(depthRaw));

  // 4. Trend Score (0-25): Is engagement increasing or declining?
  const last14Days = history.filter(h => {
    const d = new Date(h.date);
    return (now - d) / (1000 * 60 * 60 * 24) <= 14;
  }).sort((a, b) => new Date(a.date) - new Date(b.date));

  if (last14Days.length >= 4) {
    const midpoint = Math.floor(last14Days.length / 2);
    const firstHalf = last14Days.slice(0, midpoint);
    const secondHalf = last14Days.slice(midpoint);
    const avgFirst = firstHalf.reduce((s, h) => s + h.minutes, 0) / firstHalf.length;
    const avgSecond = secondHalf.reduce((s, h) => s + h.minutes, 0) / secondHalf.length;

    if (avgSecond >= avgFirst * 1.2) scores.trend = 25;       // Growing 20%+
    else if (avgSecond >= avgFirst) scores.trend = 18;         // Stable or slight growth
    else if (avgSecond >= avgFirst * 0.7) scores.trend = 10;  // Slight decline
    else if (avgSecond >= avgFirst * 0.4) scores.trend = 4;   // Significant decline
    else scores.trend = 0;                                     // Severe decline
  } else {
    scores.trend = 12; // Not enough data, assume neutral
  }

  const totalScore = scores.recency + scores.frequency + scores.depth + scores.trend;

  // Determine risk level
  let riskLevel;
  if (totalScore >= 65) riskLevel = 'low';
  else if (totalScore >= 40) riskLevel = 'medium';
  else riskLevel = 'high';

  return {
    userId: user._id,
    displayName: user.displayName,
    email: user.email,
    city: user.city,
    subscription: user.subscription,
    daysSinceActive,
    lessonsViewed: user.lessonsCount,
    totalLearningTime: user.progress?.learningTime || 0,
    scores,
    totalScore,
    riskLevel,
    riskReasons: [
      scores.recency <= 8 ? `Inactive for ${daysSinceActive} days` : null,
      scores.frequency <= 8 ? `Only ${activeDaysLast7}/7 active days last week` : null,
      scores.depth <= 8 ? 'Low content engagement' : null,
      scores.trend <= 4 ? 'Engagement declining significantly' : null
    ].filter(Boolean)
  };
}

const scoredUsers = users.map(calculateEngagementScore);

// Sort by risk (highest risk first)
scoredUsers.sort((a, b) => a.totalScore - b.totalScore);

const summary = {
  totalAnalyzed: scoredUsers.length,
  highRisk: scoredUsers.filter(u => u.riskLevel === 'high').length,
  mediumRisk: scoredUsers.filter(u => u.riskLevel === 'medium').length,
  lowRisk: scoredUsers.filter(u => u.riskLevel === 'low').length,
  avgScore: scoredUsers.length > 0 ? Math.round(scoredUsers.reduce((s, u) => s + u.totalScore, 0) / scoredUsers.length) : 0
};

return [{ json: { summary, users: scoredUsers } }];

