const data = $('Calculate Engagement Scores').first().json;
const users = data.users;

const highRisk = users.filter(u => u.riskLevel === 'high');
const mediumRisk = users.filter(u => u.riskLevel === 'medium');
const lowRisk = users.filter(u => u.riskLevel === 'low');

return [
  { json: { segment: 'high', users: highRisk } },
  { json: { segment: 'medium', users: mediumRisk } },
  { json: { segment: 'low', users: lowRisk } }
];

const highRiskUsers = $json.users || [];

// Process each high-risk user for intervention
const interventions = highRiskUsers.slice(0, 50).map(user => {
  const isPremium = user.subscription?.plan !== 'free';

  return {
    email: user.email,
    displayName: user.displayName,
    userId: user.userId,
    totalScore: user.totalScore,
    daysSinceActive: user.daysSinceActive,
    riskReasons: user.riskReasons,
    intervention: {
      type: 'immediate',
      emailSubject: isPremium 
        ? `${user.displayName}, nous avons remarque votre absence - voici un cadeau!`
        : `${user.displayName}, revenez sur Udarsy - offre speciale pour vous!`,
      offerType: isPremium ? 'extended_premium_week' : 'free_premium_3_days',
      personalizedMessage: true
    }
  };
});

return interventions.map(i => ({ json: i }));

